def find_maximal_rectangles(grid, color):
    """Find maximal rectangles of a specific color"""
    n, m = len(grid), len(grid[0])
    maximal = []

    # Find all rectangles, then filter to maximal
    all_rects = []
    for r1 in range(n):
        for r2 in range(r1, n):
            for c1 in range(m):
                for c2 in range(c1, m):
