    # Find truly maximal ones
    final_maximal = []
    for r1, r2, c1, c2 in all_rects:
        is_maximal = True
        # Check if can be extended up
        if r1 > 0:
            can_extend_up = True
            for c in range(c1, c2 + 1):
                if grid[r1-1][c] != color:
                    can_extend_up = False
                    break
            if can_extend_up:
                # Check if extending up would be rectangular
                min_c = min(c for r in range(r1-1, r1); for c in range(c1, c2+1) if grid[r][c] == color)
                max_c = max(c for r in range(r1-1, r1); for c in range(c1, c2+1) if grid[r][c] == color)
                if min_c != c1 or max_c != c2:
                    is_maximal = False
                elif r1-1 >= 0 and all(grid[r1-1][c] == color for c in range(c1, c2+1)):
                    is_maximal = False
        # Check if can be extended left
        if c1 > 0:
            for r in range(r1, r2 + 1):
                if grid[r][c1-1] != color:
                    is_maximal = False
                    break
        # Check if can be extended right
        if c2 < m - 1:
            for r in range(r1, r2 + 1):
                if grid[r][c2+1] != color:
                    is_maximal = False
                    break
        # Check if can be extended down
        if r2 < n - 1:
            for c in range(c1, c2 + 1):
                if grid[r2+1][c] != color:
                    is_maximal = False
                    break

        if is_maximal:
            final_maximal.append((r1, r2, c1, c2))

    return final_maximal

