def is_maximal_rectangle(grid, r1, r2, c1, c2, color):
    """Check if a solid rectangle is maximal (can't extend in any direction)"""
    n, m = len(grid), len(grid[0])

    # Can't extend up
    if r1 > 0:
        for c in range(c1, c2 + 1):
            if grid[r1 - 1][c] == color:
                return False

    # Can't extend down
    if r2 < n - 1:
        for c in range(c1, c2 + 1):
            if grid[r2 + 1][c] == color:
                return False

    # Can't extend left
    if c1 > 0:
        for r in range(r1, r2 + 1):
            if grid[r][c1 - 1] == color:
                return False

    # Can't extend right
    if c2 < m - 1:
        for r in range(r1, r2 + 1):
            if grid[r][c2 + 1] == color:
                return False

    return True

# Find all maximal rectangles
def find_all_maximal_rectangles(grid):
    n, m = len(grid), len(grid[0])
    maximal = []

    # For each cell, try to expand to the right and down
    for r in range(n):
        for c in range(m):
            color = grid[r][c]

            # Try different sizes
            for height in range(1, n - r + 1):
                for width in range(1, m - c + 1):
                    r2 = r + height - 1
                    c2 = c + width - 1

                    if is_solid_rectangle(grid, r, r2, c, c2, color):
                        if is_maximal_rectangle(grid, r, r2, c, c2, color):
                            rect = (r, r2, c, c2)
                            if rect not in maximal:
                                maximal.append(rect)

    return maximal

